import { 
  MeshBasicNodeMaterial, 
  PlaneGeometry, 
  Mesh, 
  Group, 
  PointLight 
} from 'three/webgpu';
import { uv, vec3, mix, positionLocal, texture, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new Group();

  // 1. DESIGN TOKENS & PALETTE
  const colors = {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // 2. STAGE BACKDROP (Dark-first, engineered gradient to avoid empty void)
  const bgGeom = new PlaneGeometry(7.5, 6.5);
  const bgMat = new MeshBasicNodeMaterial({ depthWrite: false });
  // Vertical gradient from ink (#16161d) to surface (#0b0b10)
  const vUv = uv();
  const gradColor = mix(
    vec3(0.043, 0.043, 0.0625), // #0b0b10
    vec3(0.086, 0.086, 0.113),  // #16161d
    vUv.y
  );
  bgMat.colorNode = gradColor;
  const bgMesh = new Mesh(bgGeom, bgMat);
  bgMesh.position.set(0, 0, -2.5);
  group.add(bgMesh);

  // 3. LIGHTING (Targeted key + rim, keeping albedo ceiling safe)
  const accentLight = new PointLight(colors.accent, 1.4, 5);
  accentLight.position.set(-2, 2, 1);
  group.add(accentLight);

  const whiteRimLight = new PointLight(colors.paper, 0.8, 4);
  whiteRimLight.position.set(2, -2, 1.5);
  group.add(whiteRimLight);

  // 4. MAIN SUBJECT: DISPLACEMENT TEXTURED PLANE
  // Machined surface card. Requiring tessellated plane.
  const cardGeometry = new PlaneGeometry(2.4, 1.5, 64, 64);
  const cardMaterial = new MeshBasicNodeMaterial();

  const cardGroup = new Group();
  cardGroup.position.set(0, 0, 0);
  group.add(cardGroup);

  // Pre-configured displacement and color logic
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = 'srgb';
      cardMaterial.colorNode = texture(tex);
      cardMaterial.needsUpdate = true;
    });
  }

  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((depthTex) => {
      // Apply TSL displacement node logic within the positionNode
      const depthVal = texture(depthTex).r;
      const displacementScale = uniform(0.18);
      const displacedPos = positionLocal.add(vec3(0, 0, depthVal.mul(displacementScale)));
      cardMaterial.positionNode = displacedPos;
      cardMaterial.needsUpdate = true;
    });
  }

  const cardMesh = new Mesh(cardGeometry, cardMaterial);
  cardGroup.add(cardMesh);

  // Contact shadow plane underneath the card
  const shadowGeom = new PlaneGeometry(2.6, 1.7);
  const shadowMat = new MeshBasicNodeMaterial({
    color: 0x000000,
    transparent: true,
    opacity: 0.5,
    depthWrite: false
  });
  const shadowMesh = new Mesh(shadowGeom, shadowMat);
  shadowMesh.position.set(0, -0.05, -0.08);
  cardGroup.add(shadowMesh);

  // 5. TEXT CONTENT (Bimodal Mono Labels + Metrics)
  // Value metric ("0.15") and label ("MS DEVIATION")
  const textGroup = new Group();
  textGroup.position.set(0, 0, 0.05); // Float slightly above displaced geometry
  cardGroup.add(textGroup);

  const valueText = ctx.fontAtlas.createText('0.15', {
    fontSize: 0.28,
    color: colors.paper,
    align: 'center'
  });
  valueText.position.set(0, 0.15, 0.05);
  textGroup.add(valueText);

  const labelText = ctx.fontAtlas.createText('ATELIER MS DEV', {
    fontSize: 0.08,
    color: colors.accent,
    align: 'center',
    letterSpacingPx: 3
  });
  labelText.position.set(0, -0.22, 0.05);
  textGroup.add(labelText);

  // 6. ADAPT PRIMITIVES
  const activePrimitives = [];
  if (config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach((prim) => {
      if (ctx.primitives[prim.name]) {
        const inst = ctx.primitives[prim.name](cardGroup, prim.params);
        if (inst) activePrimitives.push(inst);
      }
    });
  }

  // Fallback parallax if no primitive was registered
  if (activePrimitives.length === 0 && ctx.primitives['parallax-scroll']) {
    const defaultParallax = ctx.primitives['parallax-scroll'](cardGroup, { intensity: 0.25 });
    if (defaultParallax) activePrimitives.push(defaultParallax);
  }

  // 7. INTERACTIONS (GSAP Timeline Integrations)
  const handlerTimelines = [];

  const onPointerOver = () => {
    const tl = gsap.timeline();
    tl.to(cardGroup.position, {
      y: 0.15,
      z: 0.18,
      duration: 0.5,
      ease: 'power3.out'
    });
    // Subtle border glow effect by shifting rim lighting closer
    tl.to(accentLight.position, { x: -1.5, y: 1.5, duration: 0.5, ease: 'power2.out' }, 0);
    handlerTimelines.push(tl);
  };

  const onPointerOut = () => {
    const tl = gsap.timeline();
    tl.to(cardGroup.position, {
      y: 0,
      z: 0,
      duration: 0.6,
      ease: 'power4.out'
    });
    tl.to(accentLight.position, { x: -2, y: 2, duration: 0.6, ease: 'power4.out' }, 0);
    handlerTimelines.push(tl);
  };

  const onPointerDown = () => {
    const tl = gsap.timeline();
    tl.to(cardGroup.scale, {
      x: 0.96,
      y: 0.96,
      z: 0.96,
      duration: 0.12,
      ease: 'back.out(1.7)'
    });
    ctx.emit('hub-features.select', { id: 'stat-tile', metric: '0.15' });
    handlerTimelines.push(tl);
  };

  const onPointerUp = () => {
    const tl = gsap.timeline();
    tl.to(cardGroup.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.3,
      ease: 'power2.out'
    });
    handlerTimelines.push(tl);
  };

  // Wire events to userData handlers
  group.userData.handlers = {
    pointerover: onPointerOver,
    pointerout: onPointerOut,
    pointerdown: onPointerDown,
    pointerup: onPointerUp
  };

  // 8. CLEANUP
  group.userData.cleanup = () => {
    activePrimitives.forEach((p) => {
      if (typeof p.cleanup === 'function') p.cleanup();
      if (p.timeline) p.timeline.kill();
    });
    handlerTimelines.forEach((t) => t.kill());
    bgGeom.dispose();
    bgMat.dispose();
    cardGeometry.dispose();
    cardMaterial.dispose();
    shadowGeom.dispose();
    shadowMat.dispose();
  };

  return group;
}
